package agent

import "fmt"

const EntireNotInstalledWarning = "Powered by Entire: Tracking is enabled, but the Entire CLI is not installed or not on PATH. Install it: https://docs.entire.io/cli/installation#installation-methods"

// WrapProductionSessionStartHookCommand wraps a production session-start hook
// command so agent startup is not blocked when the `entire` binary is missing
// from PATH.
func WrapProductionSessionStartHookCommand(command string) string {
	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then echo "%s" >&2; exit 0; fi; exec %s'`,
		EntireNotInstalledWarning,
		command,
	)
}

package agent

import (
	"strings"
	"testing"
)

func TestWrapProductionSessionStartHookCommand(t *testing.T) {
	t.Parallel()

	command := WrapProductionSessionStartHookCommand("entire hooks codex session-start")

	if command == "entire hooks codex session-start" {
		t.Fatal("expected wrapped command, got raw command")
	}
	if want := `echo "` + EntireNotInstalledWarning + `" >&2`; !strings.Contains(command, want) {
		t.Fatalf("wrapped command missing warning, got %q", command)
	}
	if want := "exec entire hooks codex session-start"; !strings.Contains(command, want) {
		t.Fatalf("wrapped command missing exec target, got %q", command)
	}
}

