package agent

import (
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

const EntireNotInstalledWarning = "\n\nPowered by Entire:\n Tracking is enabled, but the Entire CLI is not installed or not on PATH.\n Installation guide: https://docs.entire.io/cli/installation#installation-methods"

// WrapProductionSessionStartHookCommand wraps a production session-start hook
// command so agent startup is not blocked when the `entire` binary is missing
// from PATH.
func WrapProductionSessionStartHookCommand(command string) string {
	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then echo "%s" >&2; exit 0; fi; exec %s'`,
		EntireNotInstalledWarning,
		command,
	)
}

// WrapProductionClaudeSessionStartHookCommand emits Claude's expected JSON hook
// response on stdout when the Entire CLI is missing from PATH.
func WrapProductionClaudeSessionStartHookCommand(command string) string {
	payload, _ := jsonutil.MarshalWithNoHTMLEscape(struct {
		SystemMessage string `json:"systemMessage,omitempty"`
	}{
		SystemMessage: EntireNotInstalledWarning,
	})

	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then printf "%%s\n" %q; exit 0; fi; exec %s'`,
		string(payload),
		command,
	)
}

